        return 'No'

    def is_balanced(s):
        stack = []
        for char in s:
            if char == '(':
                stack.append(char)
            elif char == ')':
                if not stack:
                    return False
                stack.pop()
        return not stack

    str1, str2 = lst
    for i in range(len(str1) + 1):
        for j in range(len(str2) + 1):
            new_str = str1[:i] + str2[j:]
            if is_balanced(new_str):
                return 'Yes'

    return 'No'

# Test cases
print(match_parens(['()(', ')']))  # Output: 'Yes'
print(match_parens([')', ')']))     # Output: 'No'

